        // Extract results and sort in descending order
        List<int> res = new List<int>();
        foreach (var pair in minHeap) {
            res.Add(pair.sum);
        }

        // Descending order
        res.Sort((x, y) => y.CompareTo(x)); 
        return res;
    }

